import 'package:flutter/material.dart';import '../data/income_database.dart';import '../models/income_models.dart';
class ReportPage extends StatelessWidget{const ReportPage({super.key,required this.revision});final int revision;@override Widget build(BuildContext context){final year=DateTime.now().year;return FutureBuilder<List<IncomeRecord>>(key:ValueKey(revision),future:IncomeDatabase.instance.forYear(year),builder:(context,snapshot){final records=snapshot.data??const<IncomeRecord>[];final total=records.fold<int>(0,(s,r)=>s+r.amount);final byType=<IncomeType,int>{};final bySource=<String,int>{};for(final r in records){byType[r.type]=(byType[r.type]??0)+r.amount;if(r.source!=null)bySource[r.source!]=(bySource[r.source!]??0)+r.amount;}return ListView(padding:const EdgeInsets.all(20),children:[Text('리포트',style:Theme.of(context).textTheme.headlineSmall?.copyWith(fontWeight:FontWeight.bold)),Text(year.toString()+'년 · 실제 저장 데이터 기준'),const SizedBox(height:16),Card(child:ListTile(title:const Text('기간 수입 요약'),subtitle:Text('₩'+total.toString()))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Type별 구성',style:TextStyle(fontWeight:FontWeight.bold)),...byType.entries.map((e)=>ListTile(dense:true,title:Text(e.key.label),trailing:Text('₩'+e.value.toString())))]))),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Source별 구성',style:TextStyle(fontWeight:FontWeight.bold)),...bySource.entries.map((e)=>ListTile(dense:true,title:Text(e.key),trailing:Text('₩'+e.value.toString())))]))) ]);});}}
